Lemma stk_carve : forall m lo hi (n : nat),
  stk m lo hi -> (lo <= hi - Z.of_nat n)%Z ->
  stk m lo (hi - Z.of_nat n) /\ exists junk, rw_cells segs m (hi - Z.of_nat n) [CB n junk].
